public static void main(String[] args) throws IOException {
    BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
    PrintWriter out = new PrintWriter(System.out);

    StringTokenizer st = new StringTokenizer(f.readLine());

    int n = Integer.parseInt(st.nextToken());
    int m = Integer.parseInt(st.nextToken());
    long ml = (long) m;

    int[] array = new int[n];
    st = new StringTokenizer(f.readLine());
    int num0 = 0;
    for (int k = 0; k < n; k++) {
        array[k] = Integer.parseInt(st.nextToken());
        if (array[k] == 0) num0++;
    }

    if (m >= n) {
        out.println(exp(ml, num0));
        out.close();
        return;
    }

    // first n, number of distinct values (max m+1 distinct values)
    long[][] dp = new long[n][m + 2];
    if (array[0] == 1) dp[0][1] = 1L;
    else dp[0][0] = ml;

    for (int k = 0; k < n - 1; k++) {
        for (int j = 0; j <= m + 1; j++) {
            if (dp[k][j] == 0L) continue;

            if (array[k + 1] == 1) {
                // must add a distinct value
                if (j + 1 <= m + 1) {
                    dp[k + 1][j + 1] = (dp[k + 1][j + 1] + dp[k][j]) % 998244353;
                }
            } else {
                // add a distinct value that is not mex
                long mul = ml - j;
                if (mul > 0 && j + 1 <= m + 1) {
                    dp[k + 1][j + 1] = (dp[k + 1][j + 1] + dp[k][j] * mul) % 998244353;
                }

                // add same value
                dp[k + 1][j] = (dp[k + 1][j] + dp[k][j] * (long) j) % 998244353;
            }
        }
    }

    long answer = 0L;
    for (int j = 0; j <= m + 1; j++) {
        answer = (answer + dp[n - 1][j]) % 998244353;
    }
    out.println(answer);

    out.close();
}
